export function test(): int {
  let b: bytes = bytes(4);
  if (b.length !== 4) { throw { code: "TEST_FAIL", message: "bytes: initial length mismatch" }; }
  if (b[0] !== 0 || b[1] !== 0 || b[2] !== 0 || b[3] !== 0) { throw { code: "TEST_FAIL", message: "bytes: zero-fill mismatch" }; }
  return b.length;
}

export function test(): int {
  let b: bytes = bytes(3);
  b[0] = 255;
  b[1] = 128;
  b[2] = 0;
  if (b[0] !== 255 || b[1] !== 128 || b[2] !== 0) { throw { code: "TEST_FAIL", message: "bytes: unsigned roundtrip mismatch" }; }
  return b[0] + b[1] + b[2];
}

