  let b: bytes = bytes(4);
  b[2] = 7;
  if (b[0] !== 0 || b[1] !== 0 || b[2] !== 7 || b[3] !== 0) { throw { code: "TEST_FAIL", message: "bytes: write changed more than one byte" }; }
  return 1;
}

export function test(): int {
  let b: bytes = bytes(3);
  let alias: bytes = b;
  if (b.length !== 3 || alias.length !== 3) { throw { code: "TEST_FAIL", message: "bytes: length mismatch" }; }
  let zero: bytes = bytes(0);
  if (zero.length !== 0) { throw { code: "TEST_FAIL", message: "bytes: empty length mismatch" }; }
  return b.length - alias.length + zero.length;
}

