export function test(): int {
  let a: bytes = bytes(2);
  let c: bytes = bytes(2);
  if (a === c) { throw { code: "TEST_FAIL", message: "bytes: distinct buffers compare equal" }; }
  if (!(a !== c)) { throw { code: "TEST_FAIL", message: "bytes: distinct buffers neq mismatch" }; }
  return 1;
}

export function test(): int {
  let nothing: bytes | null = null;
  if (!(nothing === null)) { throw { code: "TEST_FAIL", message: "bytes: nullable null equality mismatch" }; }
  if (nothing !== null) { throw { code: "TEST_FAIL", message: "bytes: nullable null neq mismatch" }; }
  let some: bytes | null = bytes(1);
  if (some === null) { throw { code: "TEST_FAIL", message: "bytes: nullable value equality mismatch" }; }
  if (!(null === nothing)) { throw { code: "TEST_FAIL", message: "bytes: null-nullable equality mismatch" }; }
  return 1;
}

