class Log {
  seq: int[] = [];
  buf: bytes = bytes(4);
}

function record(l: Log, tag: int): int {
  l.seq[l.seq.length] = tag;
  return tag;
}

function pick(l: Log, tag: int): bytes {
  record(l, tag);
  return l.buf;
}

export function test(): int {
  let l: Log = { seq: [], buf: bytes(4) };
  pick(l, 1)[record(l, 2)] = record(l, 3);
  if (l.seq.length !== 3) { throw { code: "TEST_FAIL", message: "bytes write must evaluate receiver, index, and RHS once each" }; }
  if (l.seq[0] !== 1 || l.seq[1] !== 2 || l.seq[2] !== 3) { throw { code: "TEST_FAIL", message: "bytes write operand order mismatch" }; }
  if (l.buf[2] !== 3) { throw { code: "TEST_FAIL", message: "bytes write value mismatch" }; }
  return 1;
}

class Log {
  seq: int[] = [];
  buf: bytes = bytes(4);
}

function record(l: Log, tag: int): int {
  l.seq[l.seq.length] = tag;
  return tag;
}

function pick(l: Log, tag: int): bytes {
  record(l, tag);
  return l.buf;
}

function badValue(l: Log): int {
  record(l, 3);
  return 300;
}

export function test(): int {
  let l: Log = { seq: [], buf: bytes(4) };
  try {
    pick(l, 1)[record(l, 2)] = badValue(l);
    throw { code: "TEST_FAIL", message: "expected E8013 before completing" };
  } catch (e) {
    if (e.code !== "E8013") { throw { code: "TEST_FAIL", message: "expected E8013, got " + e.code }; }
    if (l.seq.length !== 3 || l.seq[0] !== 1 || l.seq[1] !== 2 || l.seq[2] !== 3) { throw { code: "TEST_FAIL", message: "write validation must run after all operand side effects" }; }
  }
  if (l.buf[1] !== 0) { throw { code: "TEST_FAIL", message: "failed write must not change storage" }; }
  return 1;
}
